// Optimized Volumetric Continuous Conical Spiral using Beer Density
// Author: ChatGPT
// Paste into Shadertoy

#ifdef GL_ES
precision mediump float;
#endif


// ------------------------------------------------------------------
// Parameters: Reduced integration steps and iterations for speed.
// ------------------------------------------------------------------
const float MAX_DIST   = 50.0;
const float SURF_DIST  = 0.001;

// Volumetric integration parameters.
const float dt         = 0.2;     // Increased step size.
const int   nSteps     = 100;     // Fewer steps along the ray.
const float sigma      = 2.0;     // Absorption coefficient.

// Spiral parameters.
const float tubeRadius = 0.1;     // Tube "radius"
const float alpha      = 0.5;     // Cone opening angle (radians)
const float tMin       = -10.0;
const float tMax       = 10.0;

// ------------------------------------------------------------------
// Spiral SDF: Returns the signed distance from point p to a tube
// defined along a continuous conical spiral.
// ------------------------------------------------------------------

// Compute the position on the conical spiral at parameter t:
// s(t) = ( t*tan(alpha)*cos(t), t*tan(alpha)*sin(t), t )
vec3 spiralPos(float t) {
    float r = t * tan(alpha);
    return vec3(r * cos(t), r * sin(t), t);
}

// First derivative of s(t).
vec3 spiralDeriv(float t) {
    float A = tan(alpha);
    return vec3(A * cos(t) - A * t * sin(t),
                A * sin(t) + A * t * cos(t),
                1.0);
}

// Second derivative of s(t).
vec3 spiralSecondDeriv(float t) {
    float A = tan(alpha);
    return vec3(-2.0 * A * sin(t) - A * t * cos(t),
                 2.0 * A * cos(t) - A * t * sin(t),
                 0.0);
}

// Compute the SDF for the spiral tube.
// To speed things up, we use a reduced coarse search (20 steps)
// and fewer Newton refinement iterations (3 iterations).
float sdSpiral(vec3 p) {
    // --- Coarse Search ---
    int coarseSteps = 20;
    float bestT = tMin;
    float bestDist2 = 1e5;
    for (int i = 0; i < coarseSteps; i++) {
        float t = mix(tMin, tMax, float(i) / float(coarseSteps - 1));
        vec3 sp = spiralPos(t);
        float d2 = dot(p - sp, p - sp);
        if(d2 < bestDist2) {
            bestDist2 = d2;
            bestT = t;
        }
    }

    // --- Newton Refinement (3 iterations) ---
    float tCandidate = bestT;
    for (int iter = 0; iter < 3; iter++) {
        vec3 sPos = spiralPos(tCandidate);
        vec3 sDer = spiralDeriv(tCandidate);
        vec3 sSec = spiralSecondDeriv(tCandidate);
        vec3 diff = sPos - p;
        float f  = dot(diff, diff);
        float fprime = 2.0 * dot(diff, sDer);
        float fsec = 2.0 * (dot(sDer, sDer) + dot(diff, sSec));
        if (abs(fsec) < 1e-4) break;
        tCandidate = clamp(tCandidate - fprime / fsec, tMin, tMax);
    }

    vec3 closestPoint = spiralPos(tCandidate);
    return length(p - closestPoint) - tubeRadius;
}

// ------------------------------------------------------------------
// Volumetric integration using Beer-Lambert absorption.
// ------------------------------------------------------------------
vec3 renderVolume(vec3 ro, vec3 rd) {
    // For our density function, we define maximum density at the center.
    // Here, d_center is set to -tubeRadius so that when sdSpiral returns 0
    // (i.e. at the surface), density is lower.
    float d_center = -tubeRadius;
    float falloff = 0.2; // Controls the density profile width.

    vec3 col = vec3(0.0);
    float T = 1.0;  // Accumulated transmittance.
    float t = 0.0;

    for (int i = 0; i < nSteps; i++) {
        vec3 pos = ro + rd * t;
        float d = sdSpiral(pos);
        // Use a Gaussian profile for the density.
        float density = exp(-pow((d - d_center) / falloff, 2.0));

        float dTau = density * sigma * dt;
        float dTrans = exp(-dTau);
        float weight = T * (1.0 - dTrans);

        // Volume color can be modulated by density or position.
        vec3 volumeColor = vec3(0.2, 0.5, 1.0);
        col += weight * volumeColor;

        T *= dTrans;
        t += dt;
        if (t > MAX_DIST || T < 0.01) break;
    }

    // Background contribution.
    vec3 bgColor = vec3(0.8, 0.9, 1.0);
    col += T * bgColor;
    return col;
}

// ------------------------------------------------------------------
// Main rendering: Setup camera and cast rays.
// ------------------------------------------------------------------
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalized pixel coordinates (-1 to 1).
    vec2 uv = (fragCoord.xy / iResolution.xy) * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    // Camera setup.
    float angle = iTime * 0.3;
    vec3 ro = vec3(10.0 * cos(angle), 5.0, 10.0 * sin(angle));
    vec3 ta = vec3(0.0);

    // Camera coordinate system.
    vec3 forward = normalize(ta - ro);
    vec3 right   = normalize(cross(forward, vec3(0.0, 1.0, 0.0)));
    vec3 up      = cross(right, forward);

    vec3 rd = normalize(forward + uv.x * right + uv.y * up);

    // Compute the volumetric color along the ray.
    vec3 color = renderVolume(ro, rd);

    fragColor = vec4(color, 1.0);
}
